public define Date as record {
  year of type integer.
  month of type unsigned.
  day of type unsigned.
}.

public define Zone as record {
  minutes of type integer.
}.

public define Codec[T] as record {
  encode of type function taking (T) giving failable text.
  decode of type function taking (text) giving failable T.
}.

public define Cursor[T, S] as record {
  state of type S.
  pull of type function taking (S) giving failable Step[T, S].
}.

public define Step[T, S] as record {
  finished of type boolean.
  value of type optional T.
  state of type S.
}.

public define Entry[K, V] as record {
  key of type K.
  value of type V.
}.

public define Map[K, V] as record {
  entries of type sequence of Entry[K, V].
}.

public define Queue[T] as record {
  values of type sequence of T.
}.

public define Set[T] as record {
  values of type sequence of T.
}.

public define Stack[T] as record {
  values of type sequence of T.
}.

public define Machine[S, E] as record {
  value of type S.
  change of type function taking (S, E) giving failable S.
}.

public define Generator[T] as record {
  sample of type function taking (unsigned) giving T.
}.

public define Duration as record {
  nanoseconds of type unsigned.
}.

public define Instant as record {
  nanoseconds of type unsigned.
}.

public define Participant as record {
  prepare of type function giving failable nothing.
  commit of type function giving failable nothing.
  rollback of type function giving nothing.
}.

public define Quantity[D] as record {
  value of type decimal.
}.
